// src/components/templates/digital-name-card/titanium.tsx
// TEMPLATE: Titanium — Metallic industrial, data-dense, enterprise C-suite feel
// Research basis: Apple Metal APIs visual language + Bloomberg terminal + Porsche design

import Image from "next/image";
import type { DigitalNameCardData } from "@/lib/validators/template-schemas";

interface Props { data: DigitalNameCardData; accentColor?: string; }

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

export function TitaniumNameCard({ data, accentColor = "#94a3b8" }: Props) {
  const { fullName, pronouns, jobTitle, company, companyLogoUrl, avatarUrl, bio, tagline,
    contacts, socialLinks, skills, ctaLabel, ctaUrl, featuredQuote } = data;

  const silver = accentColor;

  return (
    <main className="min-h-screen w-full" style={{
      background: "linear-gradient(160deg, #09090f 0%, #06060b 60%, #080810 100%)",
      backgroundImage: `
        linear-gradient(rgba(148,163,184,0.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148,163,184,0.025) 1px, transparent 1px)`,
      backgroundSize: "40px 40px, 40px 40px",
    }}>
      <div className="mx-auto max-w-sm px-4 py-10">

        {/* Main card */}
        <div className="overflow-hidden rounded-2xl" style={{
          background: `linear-gradient(160deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 100%)`,
          border: "1px solid rgba(148,163,184,0.15)",
          boxShadow: `
            inset 0 1px 0 rgba(255,255,255,0.08),
            0 24px 60px rgba(0,0,0,0.6),
            0 0 0 1px rgba(148,163,184,0.05)`,
        }}>

          {/* Header row */}
          <div className="flex items-center gap-4 px-5 py-5"
            style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
            {avatarUrl ? (
              <div className="relative h-16 w-16 shrink-0 overflow-hidden rounded-xl"
                style={{ border: `1px solid ${silver}40` }}>
                <Image src={avatarUrl} alt={fullName} width={64} height={64}
                  className="h-full w-full object-cover" priority />
              </div>
            ) : (
              <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-xl text-xl font-black text-neutral-800"
                style={{ background: `linear-gradient(135deg, ${silver}, #64748b)` }}>
                {fullName.charAt(0)}
              </div>
            )}

            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <h1 className="text-lg font-black leading-tight tracking-tight text-white">
                    {fullName}
                    {pronouns && <span className="ml-1.5 text-xs font-normal text-slate-600"> ({pronouns})</span>}
                  </h1>
                  <p className="text-xs font-semibold uppercase tracking-widest mt-0.5" style={{ color: silver }}>
                    {jobTitle}
                  </p>
                </div>
                {companyLogoUrl && (
                  <Image src={companyLogoUrl} alt={company} width={48} height={20}
                    className="h-5 w-auto object-contain opacity-50 shrink-0" />
                )}
              </div>
              <p className="mt-0.5 text-xs text-slate-600">{company}</p>
            </div>
          </div>

          {/* Status bar */}
          <div className="flex items-center gap-3 px-5 py-2.5"
            style={{ background: "rgba(148,163,184,0.04)", borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
            <div className="flex items-center gap-1.5">
              <div className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
              <span className="text-[10px] text-slate-600 uppercase tracking-wider">Available</span>
            </div>
            <div className="h-3 w-px bg-slate-800" />
            {tagline && (
              <p className="text-[10px] text-slate-600 truncate flex-1">{tagline}</p>
            )}
          </div>

          {/* Bio */}
          {bio && (
            <div className="px-5 py-4" style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
              <p className="text-xs leading-relaxed text-slate-500">{bio}</p>
            </div>
          )}

          {/* Contact table — precision data layout */}
          {contacts.length > 0 && (
            <div style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  target={c.type === "website" ? "_blank" : undefined}
                  rel={c.type === "website" ? "noopener noreferrer" : undefined}
                  className="flex items-center justify-between px-5 py-3 transition-colors hover:bg-white/[0.02]"
                  style={{ borderBottom: i < contacts.length - 1 ? "1px solid rgba(148,163,184,0.05)" : "none" }}>
                  <span className="text-[10px] font-semibold uppercase tracking-widest text-slate-700">
                    {c.label ?? c.type}
                  </span>
                  <span className="font-mono text-xs text-slate-400">{c.value}</span>
                </a>
              ))}
            </div>
          )}

          {/* Skills — 2-column grid */}
          {skills && skills.length > 0 && (
            <div className="px-5 py-4" style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
              <p className="mb-2.5 text-[10px] font-semibold uppercase tracking-widest text-slate-700">Expertise</p>
              <div className="grid grid-cols-2 gap-1.5">
                {skills.map((s, i) => (
                  <div key={i} className="rounded-lg px-2.5 py-2"
                    style={{ background: "rgba(148,163,184,0.05)", border: "1px solid rgba(148,163,184,0.08)" }}>
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs text-slate-400">{s.name}</span>
                      {s.level !== undefined && (
                        <span className="text-[10px] font-mono text-slate-600">{s.level}</span>
                      )}
                    </div>
                    {s.level !== undefined && (
                      <div className="h-0.5 w-full overflow-hidden rounded-full bg-slate-900">
                        <div className="h-full rounded-full"
                          style={{ width: `${s.level}%`, background: `linear-gradient(90deg, ${silver}, #64748b)` }} />
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Social — horizontal chips */}
          {socialLinks.length > 0 && (
            <div className="px-5 py-4" style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
              <p className="mb-2.5 text-[10px] font-semibold uppercase tracking-widest text-slate-700">Connect</p>
              <div className="flex flex-wrap gap-1.5">
                {socialLinks.map((s, i) => (
                  <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                    className="rounded px-2.5 py-1.5 text-xs font-mono text-slate-500 transition-colors hover:text-white"
                    style={{ background: "rgba(148,163,184,0.06)", border: "1px solid rgba(148,163,184,0.1)" }}>
                    /{s.label ?? s.platform}
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Quote */}
          {featuredQuote && (
            <div className="px-5 py-4" style={{ borderBottom: "1px solid rgba(148,163,184,0.08)" }}>
              <p className="text-xs leading-relaxed text-slate-600 italic">&ldquo;{featuredQuote}&rdquo;</p>
            </div>
          )}

          {/* CTA */}
          {ctaLabel && ctaUrl && (
            <div className="px-5 py-4">
              <a href={ctaUrl} target="_blank" rel="noopener noreferrer"
                className="flex w-full items-center justify-between rounded-xl px-4 py-3 text-sm font-black tracking-wide text-neutral-900 transition-all hover:opacity-90"
                style={{ background: `linear-gradient(135deg, #e2e8f0, ${silver}, #64748b)` }}>
                <span>{ctaLabel}</span>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                  <path d="M7 17L17 7M7 7h10v10" />
                </svg>
              </a>
            </div>
          )}

          {/* Footer system bar */}
          <div className="flex items-center justify-between px-5 py-3"
            style={{ background: "rgba(148,163,184,0.03)", borderTop: "1px solid rgba(148,163,184,0.08)" }}>
            <span className="font-mono text-[10px] text-slate-800">PRESENCECARD</span>
            <span className="font-mono text-[10px] text-slate-800">v2.0</span>
          </div>
        </div>
      </div>
    </main>
  );
}
